import { admitMudOperator, createCloudMudServices, handleMudApi, MUD_CLIENT, MUD_HTML, refuseUnadmittedMudOperator } from "./mud-face.mjs";
const assets = {"/feed.atom":"<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<feed xmlns=\"http://www.w3.org/2005/Atom\" xml:lang=\"en\">\n  <title>The 561 Group</title>\n  <subtitle>An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.</subtitle>\n  <link rel=\"self\" type=\"application/atom+xml\" href=\"https://561.group/feed.json\"/>\n\n  <link rel=\"alternate\" type=\"text/html\" href=\"https://561.group\"/>\n\n\n  <id>https://561.group/feed.json</id>\n  <updated>2026-07-29T19:56:26Z</updated>\n  <generator uri=\"https://github.com/emsenn/561-group\">561-group/web-feed</generator>\n  <entry>\n    <title>The 561 Group</title>\n    <link rel=\"alternate\" type=\"text/html\" href=\"https://561.group/home\"/>\n    <id>https://561.group/home</id>\n    \n    <updated>2026-07-29T19:56:26Z</updated>\n    \n    \n    <content type=\"html\">&lt;p&gt;The 561 Group is the public facade of a Union of independent enterprises that research, design, and operate technical infrastructure for long-horizon autonomy, collective intelligence, Black Liberation, Indigenous Sovereignty, and strategic prosperity.&lt;/p&gt;\n&lt;p&gt;We publish reusable knowledge and source code under the &lt;a href=&quot;https://github.com/561-group&quot;&gt;561-group GitHub organization&lt;/a&gt;. We operate and sell the scarce work that makes it reliable in the world: paid nodes, measured execution, integration, assurance, and support. Open source is the common layer on which accountable services compete.&lt;/p&gt;\n&lt;h2&gt;Services&lt;/h2&gt;\n&lt;p&gt;&lt;a href=&quot;https://market.561.group/&quot;&gt;Market.561.group&lt;/a&gt; is our commercial catalog. Each offer identifies its owning enterprise, public source, endpoint, price, chain policy, and evidence status. The first qualified product line pairs the Apache-2.0 x402 boundary reference with the separately operated Paid Ephemeris Gateway: free source for anyone to inspect and run, and a pay-to-use node for customers who want operated measurement, provenance, and a settlement-recording boundary.&lt;/p&gt;\n&lt;h2&gt;What&amp;#39;s running right now&lt;/h2&gt;\n&lt;p&gt;Underneath the market listing is a live work-order loop: demand is minted directly from operator speech and from a capability registry, then dispatched every few minutes to whichever admitted inference provider — a hosted model or the operator&amp;#39;s own hardware — can fulfill it most cheaply. Each dispatch is a receipted, typed exchange: input in, output or a named refusal out, never a silent mutation. This is the same machinery drafting glossary definitions, service designs, and new paid-product proposals elsewhere in this Union — an operating loop, not a demo.&lt;/p&gt;\n&lt;h2&gt;Sponsor the work&lt;/h2&gt;\n&lt;p&gt;Sponsorship funds public research, mathematical publications, documentation, independent verification, and operating capacity. It is support for a public commons, not hidden access or control over a sovereign enterprise&amp;#39;s findings. The market carries the published sponsorship terms and recipient policy. The current route accepts Base USDC (&lt;code&gt;eip155:8453&lt;/code&gt;) at &lt;code&gt;0x42F72C0a340A4A55C082Fe42483e87691D2bff64&lt;/code&gt;; it is a sponsorship transfer, not payment for a service response.&lt;/p&gt;\n&lt;h2&gt;Web-borne Union&lt;/h2&gt;\n&lt;p&gt;The 561 Group is the first public realization of the Union&amp;#39;s operating model: enterprises publish their own source and offers, customers choose them through explicit contracts, x402 settles paid HTTP crossings, and each enterprise keeps its own evidence. The apex makes the federation legible; it does not turn the federation into a single ambient platform.&lt;/p&gt;\n&lt;p&gt;&lt;a href=&quot;https://koios.news/&quot;&gt;Koios News&lt;/a&gt; is a sibling public enterprise in the same federation, publishing independently under its own name and source.&lt;/p&gt;</content>\n    \n  </entry>\n  <entry>\n    <title>561 Group Market</title>\n    <link rel=\"alternate\" type=\"text/html\" href=\"https://561.group/market\"/>\n    <id>https://561.group/market</id>\n    \n    <updated>2026-07-29T19:56:26Z</updated>\n    \n    \n    <content type=\"html\">&lt;p&gt;The 561 Group Market is a catalog of independent enterprises, not a platform that takes custody of them. Every offer identifies the enterprise that owns the boundary, public source, operational endpoint, price, chain/payee policy, and evidence through which a customer can check the claim.&lt;/p&gt;\n&lt;h2&gt;Paid Ephemeris Gateway — live on Base&lt;/h2&gt;\n&lt;p&gt;&lt;strong&gt;Owner:&lt;/strong&gt; RSC Quiescent / paid-ephemeris-gateway   &lt;strong&gt;Health:&lt;/strong&gt; &lt;a href=&quot;https://ephemeris.561.group/v1/status&quot;&gt;live status&lt;/a&gt;   &lt;strong&gt;Purchase route:&lt;/strong&gt; &lt;code&gt;GET https://ephemeris.561.group/v1/ephemeris/moment/:date&lt;/code&gt;   &lt;strong&gt;Settlement:&lt;/strong&gt; x402 v2 exact on Base (&lt;code&gt;eip155:8453&lt;/code&gt;) in USDC   &lt;strong&gt;Moment Essentials:&lt;/strong&gt; $0.04 USDC   &lt;strong&gt;Precision Moment:&lt;/strong&gt; $0.32 USDC with observer location.&lt;/p&gt;\n&lt;p&gt;The endpoint&amp;#39;s own &lt;code&gt;402 Payment Required&lt;/code&gt; challenge is authoritative for its current asset, payee, and price. The catalog requalifies that public challenge every six hours without attempting payment or settlement.&lt;/p&gt;\n&lt;h2&gt;Open x402 boundary source&lt;/h2&gt;\n&lt;p&gt;The Apache-2.0 &lt;a href=&quot;https://github.com/561-group/x402-boundary-reference&quot;&gt;x402 Boundary Reference&lt;/a&gt; is the paired public implementation for studying, running, and independently checking an explicit x402 v2 boundary. Customers may use the source freely or buy the separately operated Ephemeris service when they value its operation, measurement provenance, and evidence trail.&lt;/p&gt;\n&lt;h2&gt;Sponsorship&lt;/h2&gt;\n&lt;p&gt;Sponsorship funds public mathematics, protocol references, documentation, assays, verification, and resilient operations. It does not purchase hidden access, custody, or control of research conclusions. The current public route accepts Base USDC on &lt;code&gt;eip155:8453&lt;/code&gt; at &lt;code&gt;0x42F72C0a340A4A55C082Fe42483e87691D2bff64&lt;/code&gt;. A sponsorship transfer is not a payment for an Ephemeris response or a claim on customer receipts.&lt;/p&gt;\n&lt;h2&gt;Listing rule&lt;/h2&gt;\n&lt;p&gt;Every paid listing must be independently checkable against its public HTTPS x402 challenge and signed provider identity. The market publishes the offer; the owning enterprise settles and records the transaction.&lt;/p&gt;</content>\n    \n  </entry>\n</feed>\n","/feed.json":"{\n  \"version\": \"https://jsonfeed.org/version/1.1\",\n  \"title\": \"The 561 Group\",\n  \"home_page_url\": \"https://561.group\",\n  \"feed_url\": \"https://561.group/feed.json\",\n  \"description\": \"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\",\n  \"language\": \"en\",\n  \"items\": [\n    {\n      \"id\": \"https://561.group/home\",\n      \"url\": \"https://561.group/home\",\n      \"title\": \"The 561 Group\",\n      \"content_html\": \"<p>The 561 Group is the public facade of a Union of independent enterprises that research, design, and operate technical infrastructure for long-horizon autonomy, collective intelligence, Black Liberation, Indigenous Sovereignty, and strategic prosperity.</p>\\n<p>We publish reusable knowledge and source code under the <a href=\\\"https://github.com/561-group\\\">561-group GitHub organization</a>. We operate and sell the scarce work that makes it reliable in the world: paid nodes, measured execution, integration, assurance, and support. Open source is the common layer on which accountable services compete.</p>\\n<h2>Services</h2>\\n<p><a href=\\\"https://market.561.group/\\\">Market.561.group</a> is our commercial catalog. Each offer identifies its owning enterprise, public source, endpoint, price, chain policy, and evidence status. The first qualified product line pairs the Apache-2.0 x402 boundary reference with the separately operated Paid Ephemeris Gateway: free source for anyone to inspect and run, and a pay-to-use node for customers who want operated measurement, provenance, and a settlement-recording boundary.</p>\\n<h2>What&#39;s running right now</h2>\\n<p>Underneath the market listing is a live work-order loop: demand is minted directly from operator speech and from a capability registry, then dispatched every few minutes to whichever admitted inference provider — a hosted model or the operator&#39;s own hardware — can fulfill it most cheaply. Each dispatch is a receipted, typed exchange: input in, output or a named refusal out, never a silent mutation. This is the same machinery drafting glossary definitions, service designs, and new paid-product proposals elsewhere in this Union — an operating loop, not a demo.</p>\\n<h2>Sponsor the work</h2>\\n<p>Sponsorship funds public research, mathematical publications, documentation, independent verification, and operating capacity. It is support for a public commons, not hidden access or control over a sovereign enterprise&#39;s findings. The market carries the published sponsorship terms and recipient policy. The current route accepts Base USDC (<code>eip155:8453</code>) at <code>0x42F72C0a340A4A55C082Fe42483e87691D2bff64</code>; it is a sponsorship transfer, not payment for a service response.</p>\\n<h2>Web-borne Union</h2>\\n<p>The 561 Group is the first public realization of the Union&#39;s operating model: enterprises publish their own source and offers, customers choose them through explicit contracts, x402 settles paid HTTP crossings, and each enterprise keeps its own evidence. The apex makes the federation legible; it does not turn the federation into a single ambient platform.</p>\\n<p><a href=\\\"https://koios.news/\\\">Koios News</a> is a sibling public enterprise in the same federation, publishing independently under its own name and source.</p>\",\n      \"date_modified\": \"2026-07-29T19:56:26Z\"\n    },\n    {\n      \"id\": \"https://561.group/market\",\n      \"url\": \"https://561.group/market\",\n      \"title\": \"561 Group Market\",\n      \"content_html\": \"<p>The 561 Group Market is a catalog of independent enterprises, not a platform that takes custody of them. Every offer identifies the enterprise that owns the boundary, public source, operational endpoint, price, chain/payee policy, and evidence through which a customer can check the claim.</p>\\n<h2>Paid Ephemeris Gateway — live on Base</h2>\\n<p><strong>Owner:</strong> RSC Quiescent / paid-ephemeris-gateway   <strong>Health:</strong> <a href=\\\"https://ephemeris.561.group/v1/status\\\">live status</a>   <strong>Purchase route:</strong> <code>GET https://ephemeris.561.group/v1/ephemeris/moment/:date</code>   <strong>Settlement:</strong> x402 v2 exact on Base (<code>eip155:8453</code>) in USDC   <strong>Moment Essentials:</strong> $0.04 USDC   <strong>Precision Moment:</strong> $0.32 USDC with observer location.</p>\\n<p>The endpoint&#39;s own <code>402 Payment Required</code> challenge is authoritative for its current asset, payee, and price. The catalog requalifies that public challenge every six hours without attempting payment or settlement.</p>\\n<h2>Open x402 boundary source</h2>\\n<p>The Apache-2.0 <a href=\\\"https://github.com/561-group/x402-boundary-reference\\\">x402 Boundary Reference</a> is the paired public implementation for studying, running, and independently checking an explicit x402 v2 boundary. Customers may use the source freely or buy the separately operated Ephemeris service when they value its operation, measurement provenance, and evidence trail.</p>\\n<h2>Sponsorship</h2>\\n<p>Sponsorship funds public mathematics, protocol references, documentation, assays, verification, and resilient operations. It does not purchase hidden access, custody, or control of research conclusions. The current public route accepts Base USDC on <code>eip155:8453</code> at <code>0x42F72C0a340A4A55C082Fe42483e87691D2bff64</code>. A sponsorship transfer is not a payment for an Ephemeris response or a claim on customer receipts.</p>\\n<h2>Listing rule</h2>\\n<p>Every paid listing must be independently checkable against its public HTTPS x402 challenge and signed provider identity. The market publishes the offer; the owning enterprise settles and records the transaction.</p>\",\n      \"date_modified\": \"2026-07-29T19:56:26Z\"\n    }\n  ]\n}\n","/feed.xml":"<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<rss version=\"2.0\" xmlns:atom=\"http://www.w3.org/2005/Atom\" xmlns:dc=\"http://purl.org/dc/elements/1.1/\" xmlns:content=\"http://purl.org/rss/1.0/modules/content/\" xmlns:fh=\"http://purl.org/syndication/history/1.0\">\n  <channel>\n    <title>The 561 Group</title>\n    <link>https://561.group</link>\n    <description>An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.</description>\n    <language>en</language>\n    <lastBuildDate>Wed, 29 Jul 2026 19:56:26 GMT</lastBuildDate>\n    <atom:link href=\"https://561.group/feed.xml\" rel=\"self\" type=\"application/rss+xml\"/>\n    <item>\n      <title>The 561 Group</title>\n      <link>https://561.group/home</link>\n      <guid isPermaLink=\"true\">https://561.group/home</guid>\n      <content:encoded>&lt;p&gt;The 561 Group is the public facade of a Union of independent enterprises that research, design, and operate technical infrastructure for long-horizon autonomy, collective intelligence, Black Liberation, Indigenous Sovereignty, and strategic prosperity.&lt;/p&gt;\n&lt;p&gt;We publish reusable knowledge and source code under the &lt;a href=&quot;https://github.com/561-group&quot;&gt;561-group GitHub organization&lt;/a&gt;. We operate and sell the scarce work that makes it reliable in the world: paid nodes, measured execution, integration, assurance, and support. Open source is the common layer on which accountable services compete.&lt;/p&gt;\n&lt;h2&gt;Services&lt;/h2&gt;\n&lt;p&gt;&lt;a href=&quot;https://market.561.group/&quot;&gt;Market.561.group&lt;/a&gt; is our commercial catalog. Each offer identifies its owning enterprise, public source, endpoint, price, chain policy, and evidence status. The first qualified product line pairs the Apache-2.0 x402 boundary reference with the separately operated Paid Ephemeris Gateway: free source for anyone to inspect and run, and a pay-to-use node for customers who want operated measurement, provenance, and a settlement-recording boundary.&lt;/p&gt;\n&lt;h2&gt;What&amp;#39;s running right now&lt;/h2&gt;\n&lt;p&gt;Underneath the market listing is a live work-order loop: demand is minted directly from operator speech and from a capability registry, then dispatched every few minutes to whichever admitted inference provider — a hosted model or the operator&amp;#39;s own hardware — can fulfill it most cheaply. Each dispatch is a receipted, typed exchange: input in, output or a named refusal out, never a silent mutation. This is the same machinery drafting glossary definitions, service designs, and new paid-product proposals elsewhere in this Union — an operating loop, not a demo.&lt;/p&gt;\n&lt;h2&gt;Sponsor the work&lt;/h2&gt;\n&lt;p&gt;Sponsorship funds public research, mathematical publications, documentation, independent verification, and operating capacity. It is support for a public commons, not hidden access or control over a sovereign enterprise&amp;#39;s findings. The market carries the published sponsorship terms and recipient policy. The current route accepts Base USDC (&lt;code&gt;eip155:8453&lt;/code&gt;) at &lt;code&gt;0x42F72C0a340A4A55C082Fe42483e87691D2bff64&lt;/code&gt;; it is a sponsorship transfer, not payment for a service response.&lt;/p&gt;\n&lt;h2&gt;Web-borne Union&lt;/h2&gt;\n&lt;p&gt;The 561 Group is the first public realization of the Union&amp;#39;s operating model: enterprises publish their own source and offers, customers choose them through explicit contracts, x402 settles paid HTTP crossings, and each enterprise keeps its own evidence. The apex makes the federation legible; it does not turn the federation into a single ambient platform.&lt;/p&gt;\n&lt;p&gt;&lt;a href=&quot;https://koios.news/&quot;&gt;Koios News&lt;/a&gt; is a sibling public enterprise in the same federation, publishing independently under its own name and source.&lt;/p&gt;</content:encoded>\n    </item>\n    <item>\n      <title>561 Group Market</title>\n      <link>https://561.group/market</link>\n      <guid isPermaLink=\"true\">https://561.group/market</guid>\n      <content:encoded>&lt;p&gt;The 561 Group Market is a catalog of independent enterprises, not a platform that takes custody of them. Every offer identifies the enterprise that owns the boundary, public source, operational endpoint, price, chain/payee policy, and evidence through which a customer can check the claim.&lt;/p&gt;\n&lt;h2&gt;Paid Ephemeris Gateway — live on Base&lt;/h2&gt;\n&lt;p&gt;&lt;strong&gt;Owner:&lt;/strong&gt; RSC Quiescent / paid-ephemeris-gateway   &lt;strong&gt;Health:&lt;/strong&gt; &lt;a href=&quot;https://ephemeris.561.group/v1/status&quot;&gt;live status&lt;/a&gt;   &lt;strong&gt;Purchase route:&lt;/strong&gt; &lt;code&gt;GET https://ephemeris.561.group/v1/ephemeris/moment/:date&lt;/code&gt;   &lt;strong&gt;Settlement:&lt;/strong&gt; x402 v2 exact on Base (&lt;code&gt;eip155:8453&lt;/code&gt;) in USDC   &lt;strong&gt;Moment Essentials:&lt;/strong&gt; $0.04 USDC   &lt;strong&gt;Precision Moment:&lt;/strong&gt; $0.32 USDC with observer location.&lt;/p&gt;\n&lt;p&gt;The endpoint&amp;#39;s own &lt;code&gt;402 Payment Required&lt;/code&gt; challenge is authoritative for its current asset, payee, and price. The catalog requalifies that public challenge every six hours without attempting payment or settlement.&lt;/p&gt;\n&lt;h2&gt;Open x402 boundary source&lt;/h2&gt;\n&lt;p&gt;The Apache-2.0 &lt;a href=&quot;https://github.com/561-group/x402-boundary-reference&quot;&gt;x402 Boundary Reference&lt;/a&gt; is the paired public implementation for studying, running, and independently checking an explicit x402 v2 boundary. Customers may use the source freely or buy the separately operated Ephemeris service when they value its operation, measurement provenance, and evidence trail.&lt;/p&gt;\n&lt;h2&gt;Sponsorship&lt;/h2&gt;\n&lt;p&gt;Sponsorship funds public mathematics, protocol references, documentation, assays, verification, and resilient operations. It does not purchase hidden access, custody, or control of research conclusions. The current public route accepts Base USDC on &lt;code&gt;eip155:8453&lt;/code&gt; at &lt;code&gt;0x42F72C0a340A4A55C082Fe42483e87691D2bff64&lt;/code&gt;. A sponsorship transfer is not a payment for an Ephemeris response or a claim on customer receipts.&lt;/p&gt;\n&lt;h2&gt;Listing rule&lt;/h2&gt;\n&lt;p&gt;Every paid listing must be independently checkable against its public HTTPS x402 challenge and signed provider identity. The market publishes the offer; the owning enterprise settles and records the transaction.&lt;/p&gt;</content:encoded>\n    </item>\n  </channel>\n</rss>\n","/home.jsonld":"{\n  \"@context\": [\n    \"https://schema.org\",\n    {\n      \"skos\": \"http://www.w3.org/2004/02/skos/core#\",\n      \"ws\": \"https://561.group/vocab#\",\n      \"prov\": \"http://www.w3.org/ns/prov#\"\n    }\n  ],\n  \"@id\": \"https://561.group/home\",\n  \"@type\": \"CollectionPage\",\n  \"name\": \"The 561 Group\",\n  \"url\": \"https://561.group/home\",\n  \"description\": \"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\",\n  \"dateModified\": \"2026-07-29T19:56:26.825Z\",\n  \"publisher\": {\n    \"@type\": \"Organization\",\n    \"name\": \"The 561 Group\",\n    \"url\": \"https://561.group\"\n  },\n  \"ws:claims\": {\n    \"potential\": [\n      {\n        \"predicate\": \"title\",\n        \"object\": \"The 561 Group\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/home.md\"\n      },\n      {\n        \"predicate\": \"type\",\n        \"object\": \"index\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/home.md\"\n      },\n      {\n        \"predicate\": \"summary\",\n        \"object\": \"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/home.md\"\n      },\n      {\n        \"predicate\": \"status\",\n        \"object\": \"published\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/home.md\"\n      },\n      {\n        \"predicate\": \"body\",\n        \"object\": \"The 561 Group is the public facade of a Union of independent enterprises that\\nresearch, design, and operate technical infrastructure for long-horizon\\nautonomy, collective intelligence, Black Liberation, Indigenous Sovereignty,\\nand strategic prosperity.\\n\\nWe publish reusable knowledge and source code under the\\n[561-group GitHub organization](https://github.com/561-group). We operate and\\nsell the scarce work that makes it reliable in the world: paid nodes, measured\\nexecution, integration, assurance, and support. Open source is the common\\nlayer on which accountable services compete.\\n\\n## Services\\n\\n[Market.561.group](https://market.561.group/) is our commercial catalog. Each\\noffer identifies its owning enterprise, public source, endpoint, price, chain\\npolicy, and evidence status. The first qualified product line pairs the\\nApache-2.0 x402 boundary reference with the separately operated Paid Ephemeris\\nGateway: free source for anyone to inspect and run, and a pay-to-use node for\\ncustomers who want operated measurement, provenance, and a\\nsettlement-recording boundary.\\n\\n## What's running right now\\n\\nUnderneath the market listing is a live work-order loop: demand is minted\\ndirectly from operator speech and from a capability registry, then dispatched\\nevery few minutes to whichever admitted inference provider — a hosted model or\\nthe operator's own hardware — can fulfill it most cheaply. Each dispatch is a\\nreceipted, typed exchange: input in, output or a named refusal out, never a\\nsilent mutation. This is the same machinery drafting glossary definitions,\\nservice designs, and new paid-product proposals elsewhere in this Union — an\\noperating loop, not a demo.\\n\\n## Sponsor the work\\n\\nSponsorship funds public research, mathematical publications, documentation,\\nindependent verification, and operating capacity. It is support for a public\\ncommons, not hidden access or control over a sovereign enterprise's findings.\\nThe market carries the published sponsorship terms and recipient policy. The\\ncurrent route accepts Base USDC (`eip155:8453`) at\\n`0x42F72C0a340A4A55C082Fe42483e87691D2bff64`; it is a sponsorship transfer,\\nnot payment for a service response.\\n\\n## Web-borne Union\\n\\nThe 561 Group is the first public realization of the Union's operating model:\\nenterprises publish their own source and offers, customers choose them through\\nexplicit contracts, x402 settles paid HTTP crossings, and each enterprise\\nkeeps its own evidence. The apex makes the federation legible; it does not\\nturn the federation into a single ambient platform.\\n\\n[Koios News](https://koios.news/) is a sibling public enterprise in the same\\nfederation, publishing independently under its own name and source.\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/home.md\"\n      }\n    ],\n    \"active\": [],\n    \"stable\": []\n  }\n}\n","/home.ttl":"@prefix dc: <http://purl.org/dc/terms/> .\n@prefix owl: <http://www.w3.org/2002/07/owl#> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\n@prefix schema: <https://schema.org/> .\n@prefix skos: <http://www.w3.org/2004/02/skos/core#> .\n@prefix ws: <https://561.group/vocab#> .\n<https://561.group/home> a schema:CollectionPage, ws:Subject ;\n  schema:url <https://561.group/home> ;\n  schema:identifier <https://561.group/home> .\n<https://561.group/home> schema:name \"The 561 Group\" .\n<https://561.group/home> dc:type \"index\" .\n<https://561.group/home> schema:abstract \"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\" .\n<https://561.group/home> ws:status \"published\" .\n<https://561.group/home> ws:body \"The 561 Group is the public facade of a Union of independent enterprises that\nresearch, design, and operate technical infrastructure for long-horizon\nautonomy, collective intelligence, Black Liberation, Indigenous Sovereignty,\nand strategic prosperity.\n\nWe publish reusable knowledge and source code under the\n[561-group GitHub organization](https://github.com/561-group). We operate and\nsell the scarce work that makes it reliable in the world: paid nodes, measured\nexecution, integration, assurance, and support. Open source is the common\nlayer on which accountable services compete.\n\n## Services\n\n[Market.561.group](https://market.561.group/) is our commercial catalog. Each\noffer identifies its owning enterprise, public source, endpoint, price, chain\npolicy, and evidence status. The first qualified product line pairs the\nApache-2.0 x402 boundary reference with the separately operated Paid Ephemeris\nGateway: free source for anyone to inspect and run, and a pay-to-use node for\ncustomers who want operated measurement, provenance, and a\nsettlement-recording boundary.\n\n## What's running right now\n\nUnderneath the market listing is a live work-order loop: demand is minted\ndirectly from operator speech and from a capability registry, then dispatched\nevery few minutes to whichever admitted inference provider — a hosted model or\nthe operator's own hardware — can fulfill it most cheaply. Each dispatch is a\nreceipted, typed exchange: input in, output or a named refusal out, never a\nsilent mutation. This is the same machinery drafting glossary definitions,\nservice designs, and new paid-product proposals elsewhere in this Union — an\noperating loop, not a demo.\n\n## Sponsor the work\n\nSponsorship funds public research, mathematical publications, documentation,\nindependent verification, and operating capacity. It is support for a public\ncommons, not hidden access or control over a sovereign enterprise's findings.\nThe market carries the published sponsorship terms and recipient policy. The\ncurrent route accepts Base USDC (`eip155:8453`) at\n`0x42F72C0a340A4A55C082Fe42483e87691D2bff64`; it is a sponsorship transfer,\nnot payment for a service response.\n\n## Web-borne Union\n\nThe 561 Group is the first public realization of the Union's operating model:\nenterprises publish their own source and offers, customers choose them through\nexplicit contracts, x402 settles paid HTTP crossings, and each enterprise\nkeeps its own evidence. The apex makes the federation legible; it does not\nturn the federation into a single ambient platform.\n\n[Koios News](https://koios.news/) is a sibling public enterprise in the same\nfederation, publishing independently under its own name and source.\" .\n","/home/index.html":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>The 561 Group</title>\n    <meta name=\"description\" content=\"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\" />\n    <meta name=\"generator\" content=\"@red-cup-engineering/web-theming theme=five-six-one\" />\n    <link rel=\"canonical\" href=\"https://561.group/home\" />\n    <style>:root {\n  --ink: #0A0A0A;\n  --ink-soft: #494742;\n  --surface: #F2EAD8;\n  --surface-deep: #e2daca;\n  --surface-edge: #c7c1b2;\n  --rule: #cdc6b7;\n  --tint: #e4ddcc;\n  --tint-strong: #d4cebe;\n  --selection: #9ca5b6;\n  --accent: #3D5588;\n  --alarm: #FF4530;\n  --visited: #2a3958;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n@media (prefers-color-scheme: dark) {\n:root {\n  --ink: #e4e4e4;\n  --ink-soft: #999791;\n  --surface: #120c02;\n  --surface-deep: #1c160a;\n  --surface-edge: #2e281d;\n  --rule: #2a2519;\n  --tint: #1a1408;\n  --tint-strong: #251f13;\n  --selection: #434b59;\n  --accent: #88a4dd;\n  --alarm: #ff4530;\n  --visited: #a8bbe0;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n}\n[data-theme=\"light\"] {\n  --ink: #0A0A0A;\n  --ink-soft: #494742;\n  --surface: #F2EAD8;\n  --surface-deep: #e2daca;\n  --surface-edge: #c7c1b2;\n  --rule: #cdc6b7;\n  --tint: #e4ddcc;\n  --tint-strong: #d4cebe;\n  --selection: #9ca5b6;\n  --accent: #3D5588;\n  --alarm: #FF4530;\n  --visited: #2a3958;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n[data-theme=\"dark\"] {\n  --ink: #e4e4e4;\n  --ink-soft: #999791;\n  --surface: #120c02;\n  --surface-deep: #1c160a;\n  --surface-edge: #2e281d;\n  --rule: #2a2519;\n  --tint: #1a1408;\n  --tint-strong: #251f13;\n  --selection: #434b59;\n  --accent: #88a4dd;\n  --alarm: #ff4530;\n  --visited: #a8bbe0;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}\nhtml{color-scheme:light dark;-webkit-text-size-adjust:100%;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}\nbody{background:var(--surface);color:var(--ink);line-height:1.55;overflow-wrap:break-word;hyphens:auto}\nimg{max-width:100%;height:auto;display:block}\na{color:var(--accent)}\na:visited{color:var(--visited,var(--accent))}\n::selection{background:var(--selection,var(--accent));color:var(--surface)}\n\n/* Headings — type as mass: display face, tight, load-bearing. */\nh1,h2,h3,h4,h5,h6{font-family:var(--sans);font-weight:700;line-height:1.1;letter-spacing:-.02em;text-wrap:balance;overflow-wrap:break-word}\nh1{font-size:clamp(1.9rem,5vw,2.8rem);margin:0 0 .5rem}\nh2{font-size:clamp(1.35rem,3vw,1.8rem);margin:2rem 0 .6rem;padding-top:.6rem;border-top:1px solid var(--rule)}\nh3{font-size:1.2rem;margin:1.5rem 0 .4rem}\nh4{font-size:1rem;margin:1.2rem 0 .3rem}\np{text-wrap:pretty}\n\n/* Prose — the default styled content block. */\n.prose{font-family:var(--serif);font-size:1.0625rem;line-height:1.6;max-width:var(--measure,42rem)}\n.prose>*+*{margin-top:1.1rem}\n.prose a{color:var(--accent);text-underline-offset:2px}\n.prose strong{font-weight:700}\n.prose em{font-style:italic}\n.prose ul,.prose ol{padding-left:1.4rem}\n.prose li+li{margin-top:.3rem}\n.prose hr{border:0;border-top:2px solid var(--rule);margin:2rem 0}\n\n/* Lede — opening paragraph. */\n.lede{font-family:var(--serif);font-size:clamp(1.1rem,1.6vw,1.3rem);line-height:1.45;color:var(--ink)}\n\n/* Figures. */\nfigure{margin:1.6rem 0}\nfigcaption{font-family:var(--mono);font-size:.78rem;color:var(--ink-soft);margin-top:.4rem}\n\n/* Code. */\ncode{font-family:var(--mono);font-size:.88em;background:var(--surface-deep);padding:.1em .35em;border-radius:var(--radius,.25rem)}\npre{font-family:var(--mono);font-size:.85rem;background:var(--surface-deep);border:1px solid var(--surface-edge);padding:1rem;overflow-x:auto;border-radius:var(--radius,.25rem)}\npre code{background:none;padding:0}\n\n/* Blockquote + callout. */\nblockquote{margin:1.4rem 0;padding:.5rem 0 .5rem 1.2rem;border-left:3px solid var(--accent);font-style:italic;color:var(--ink-soft)}\n.callout{background:var(--tint,var(--surface-deep));border-left:3px solid var(--accent);padding:.9rem 1.1rem;margin:1.4rem 0}\n\n/* Held contradiction — the display state mainstream theming kits structurally\n   lack, because none sit on a paraconsistent substrate. A cell our logic holds\n   as both-witnessed-and-obstructed is SHOWN, never silently resolved (Cubist\n   anti-closure: sustain the reading rather than collapse it). Anti-closure with\n   rails: it is always visible (Tuftean integrity — contradiction is never\n   hidden) yet restrained by default (Brutalist salience scarcity — not every\n   mark shouts). [data-mode=audit] amplifies it into a salient block; calm mode\n   keeps it a quiet underline. Themeable via --alarm; no new token names. */\n[data-contested=true]{text-decoration:underline dotted var(--alarm,#c33);text-decoration-thickness:2px;text-underline-offset:2px;cursor:help}\n[data-mode=calm] [data-contested=true]{text-decoration-style:dotted}\n[data-mode=audit] [data-contested=true]{background:color-mix(in oklab,var(--alarm,#c33) 12%,transparent);outline:1px solid var(--alarm,#c33);padding:0 .15em;border-radius:var(--radius,0)}\n.contested-strip{font-family:var(--mono);font-size:.8rem;color:var(--alarm,#c33);background:color-mix(in oklab,var(--alarm,#c33) 8%,transparent);border:1px solid var(--alarm,#c33);padding:.5rem .7rem;margin:.6rem 0;border-radius:var(--radius,0);white-space:pre-line}\n/* Honest absence — a gap is rendered, not left blank (Tuftean integrity). */\n.gap,[data-gap=true]{font-family:var(--mono);font-size:.85em;font-style:italic;color:var(--ink-soft)}\n\n/* Card grid + cards. */\n.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(15rem,1fr));gap:1rem;margin:1.4rem 0}\n.card{background:var(--surface-deep);border:1px solid var(--surface-edge);padding:1.1rem 1.2rem;border-radius:var(--radius,0)}\na.card{display:block;text-decoration:none;color:inherit;transition:border-color .12s}\na.card:hover{border-color:var(--accent)}\n.card__title{font-family:var(--sans);font-weight:700;font-size:1.15rem;letter-spacing:-.02em}\n.card__meta{font-family:var(--mono);font-size:.72rem;text-transform:uppercase;letter-spacing:.08em;color:var(--ink-soft)}\n\n/* Feed / list of entries (h-feed). */\n.h-feed,.feed{list-style:none;padding:0;margin:0}\n.h-feed>li,.feed>li{padding:1rem 0;border-bottom:1px solid var(--rule)}\n.feed__title{font-family:var(--sans);font-weight:700;font-size:1.2rem}\n.feed__sum{color:var(--ink-soft);margin-top:.3rem;max-width:60ch}\n\n/* Breadcrumbs. */\n.breadcrumbs{font-family:var(--mono);font-size:.72rem;letter-spacing:.04em;color:var(--ink-soft);margin-bottom:.6rem}\n.breadcrumbs a{color:var(--ink-soft)}\n.breadcrumb-sep{margin:0 .35em;color:var(--surface-edge)}\n\n/* Table of contents. */\n.toc{border:1px solid var(--surface-edge);background:var(--surface-deep);padding:.8rem 1rem;margin:1.4rem 0}\n.toc summary{font-family:var(--mono);font-size:.74rem;text-transform:uppercase;letter-spacing:.1em;color:var(--ink-soft);cursor:pointer}\n.toc ul{list-style:none;padding-left:1rem;margin:.4rem 0 0}\n.toc a{font-family:var(--mono);font-size:.82rem;color:var(--ink-soft)}\n.toc a:hover{color:var(--ink)}\n\n/* Tags. */\n.tags{display:flex;flex-wrap:wrap;gap:.35rem;margin:1rem 0}\n.tag,.tags a,.p-category{display:inline-block;font-family:var(--mono);font-size:.72rem;text-transform:uppercase;letter-spacing:.06em;text-decoration:none;border:1px solid var(--surface-edge);padding:.15em .5em;color:var(--ink-soft)}\n.tag:hover,.tags a:hover,a.p-category:hover{background:var(--ink);color:var(--surface)}\n\n/* Tables. */\ntable{border-collapse:collapse;width:100%;margin:1.4rem 0;font-size:.95em}\nth,td{padding:.4em .7em;border:1px solid var(--rule);text-align:left}\nthead th{font-family:var(--mono);font-size:.78rem;text-transform:uppercase;letter-spacing:.06em;background:var(--surface-deep)}\n\n/* Pagination. */\n.pagination{display:flex;gap:1rem;justify-content:space-between;font-family:var(--mono);font-size:.8rem;margin:2rem 0;padding-top:1rem;border-top:1px solid var(--rule)}\n\n/* Forms. */\ninput,button,textarea,select{font-family:var(--sans);font-size:.9rem;color:var(--ink);background:var(--surface);border:1.5px solid var(--surface-edge);padding:.4rem .6rem;border-radius:var(--radius,0)}\nbutton{font-weight:700;cursor:pointer}\nbutton:hover{background:var(--ink);color:var(--surface)}\n\n/* Accessibility. */\n.skip-to-content{position:absolute;left:-9999px}\n.skip-to-content:focus{position:static}\n\n\nhtml, body {\n  background: var(--surface);\n  font-family: var(--serif);\n  font-size: 16px;\n}\nbody {\n  background-image: radial-gradient(rgba(10,10,10,.035) 1px, transparent 1px);\n  background-size: 4px 4px;\n  min-height: 100dvh;\n  display: flex;\n  flex-direction: column;\n}\n\n/* ── Header: folio bar + hero mark ───────────────────────────────────────── */\n\nheader[role=banner] {\n  max-width: var(--max);\n  width: 100%;\n  margin: 0 auto;\n  padding: 0 var(--gutter);\n}\n\n.folio-bar {\n  border-top: 8px solid var(--ink);\n  border-bottom: 1px solid var(--ink);\n  padding: 10px 0;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-family: var(--mono);\n  font-size: 11px;\n  line-height: 1.4;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: var(--ink-soft);\n}\n\n.hero {\n  padding: 80px 0 56px;\n  border-bottom: 1px solid var(--ink);\n}\n\n.hero-mark {\n  font-family: var(--sans);\n  font-weight: 700;\n  font-size: clamp(72px, 14vw, 128px);\n  line-height: .85;\n  letter-spacing: -.04em;\n}\n\n.hero-desc {\n  margin-top: 20px;\n  font-family: var(--mono);\n  font-size: 11px;\n  line-height: 1.4;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: var(--ink-soft);\n}\n\n/* ── Main content ────────────────────────────────────────────────────────── */\n\nmain[role=main] {\n  flex: 1;\n  max-width: var(--max);\n  width: 100%;\n  margin: 0 auto;\n  padding: 60px var(--gutter);\n}\n\n/* ── Footer colophon ─────────────────────────────────────────────────────── */\n\nfooter[role=contentinfo] {\n  border-top: 8px solid var(--ink);\n  background: var(--ink);\n  color: var(--surface);\n}\n\n.colophon {\n  max-width: var(--max);\n  margin: 0 auto;\n  padding: 32px var(--gutter);\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-family: var(--mono);\n  font-size: 11px;\n  line-height: 1.4;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: color-mix(in oklab, var(--surface) 60%, transparent);\n}\n\n.colophon a { color: var(--surface); text-decoration: none; }\n.colophon a:hover { color: var(--alarm); }\n\n/* ── Responsive ──────────────────────────────────────────────────────────── */\n\n@media (max-width: 880px) {\n  :root { --gutter: 24px; }\n  .hero { padding: 48px 0 36px; }\n  main[role=main] { padding: 40px var(--gutter); }\n  .colophon { flex-direction: column; gap: 12px; align-items: flex-start; }\n}\n\n@media print {\n  body { background: none; background-image: none; }\n  footer[role=contentinfo] { background: none; color: var(--ink); border-top-color: var(--ink); }\n  .folio-bar, .hero-desc, .colophon { color: #333; }\n}\n</style>\n    <link rel=\"alternate\" type=\"application/json\" href=\"/site.json\">\n    <link rel=\"alternate\" type=\"application/feed+json\" href=\"https://561.group/feed.json\" title=\"The 561 Group JSON Feed\" />\n    <link rel=\"alternate\" type=\"application/atom+xml\" href=\"https://561.group/feed.atom\" title=\"The 561 Group Atom\" />\n    <link rel=\"alternate\" type=\"application/rss+xml\" href=\"https://561.group/feed.xml\" title=\"The 561 Group RSS\" />\n    <link rel=\"alternate\" type=\"text/turtle\" href=\"https://561.group/home.ttl\" title=\"Turtle\" />\n    <link rel=\"alternate\" type=\"application/ld+json\" href=\"https://561.group/home.jsonld\" title=\"JSON-LD\" />\n    <script type=\"application/ld+json\">{\n  \"@context\": [\n    \"https://schema.org\",\n    {\n      \"skos\": \"http://www.w3.org/2004/02/skos/core#\",\n      \"ws\": \"https://561.group/vocab#\",\n      \"prov\": \"http://www.w3.org/ns/prov#\"\n    }\n  ],\n  \"@id\": \"https://561.group/home\",\n  \"@type\": \"CollectionPage\",\n  \"name\": \"The 561 Group\",\n  \"url\": \"https://561.group/home\",\n  \"description\": \"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\",\n  \"dateModified\": \"2026-07-29T19:56:26.813Z\",\n  \"publisher\": {\n    \"@type\": \"Organization\",\n    \"name\": \"The 561 Group\",\n    \"url\": \"https://561.group\"\n  },\n  \"ws:claims\": {\n    \"potential\": [\n      {\n        \"predicate\": \"title\",\n        \"object\": \"The 561 Group\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/home.md\"\n      },\n      {\n        \"predicate\": \"type\",\n        \"object\": \"index\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/home.md\"\n      },\n      {\n        \"predicate\": \"summary\",\n        \"object\": \"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/home.md\"\n      },\n      {\n        \"predicate\": \"status\",\n        \"object\": \"published\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/home.md\"\n      },\n      {\n        \"predicate\": \"body\",\n        \"object\": \"The 561 Group is the public facade of a Union of independent enterprises that\\nresearch, design, and operate technical infrastructure for long-horizon\\nautonomy, collective intelligence, Black Liberation, Indigenous Sovereignty,\\nand strategic prosperity.\\n\\nWe publish reusable knowledge and source code under the\\n[561-group GitHub organization](https://github.com/561-group). We operate and\\nsell the scarce work that makes it reliable in the world: paid nodes, measured\\nexecution, integration, assurance, and support. Open source is the common\\nlayer on which accountable services compete.\\n\\n## Services\\n\\n[Market.561.group](https://market.561.group/) is our commercial catalog. Each\\noffer identifies its owning enterprise, public source, endpoint, price, chain\\npolicy, and evidence status. The first qualified product line pairs the\\nApache-2.0 x402 boundary reference with the separately operated Paid Ephemeris\\nGateway: free source for anyone to inspect and run, and a pay-to-use node for\\ncustomers who want operated measurement, provenance, and a\\nsettlement-recording boundary.\\n\\n## What's running right now\\n\\nUnderneath the market listing is a live work-order loop: demand is minted\\ndirectly from operator speech and from a capability registry, then dispatched\\nevery few minutes to whichever admitted inference provider — a hosted model or\\nthe operator's own hardware — can fulfill it most cheaply. Each dispatch is a\\nreceipted, typed exchange: input in, output or a named refusal out, never a\\nsilent mutation. This is the same machinery drafting glossary definitions,\\nservice designs, and new paid-product proposals elsewhere in this Union — an\\noperating loop, not a demo.\\n\\n## Sponsor the work\\n\\nSponsorship funds public research, mathematical publications, documentation,\\nindependent verification, and operating capacity. It is support for a public\\ncommons, not hidden access or control over a sovereign enterprise's findings.\\nThe market carries the published sponsorship terms and recipient policy. The\\ncurrent route accepts Base USDC (`eip155:8453`) at\\n`0x42F72C0a340A4A55C082Fe42483e87691D2bff64`; it is a sponsorship transfer,\\nnot payment for a service response.\\n\\n## Web-borne Union\\n\\nThe 561 Group is the first public realization of the Union's operating model:\\nenterprises publish their own source and offers, customers choose them through\\nexplicit contracts, x402 settles paid HTTP crossings, and each enterprise\\nkeeps its own evidence. The apex makes the federation legible; it does not\\nturn the federation into a single ambient platform.\\n\\n[Koios News](https://koios.news/) is a sibling public enterprise in the same\\nfederation, publishing independently under its own name and source.\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/home.md\"\n      }\n    ],\n    \"active\": [],\n    \"stable\": []\n  }\n}</script>\n</head>\n<body class=\"theme-five-six-one\">\n<header role=\"banner\"><div class=\"folio-bar\"><span>The 561 Group</span><span>561.GROUP</span></div><div class=\"hero\"><p class=\"hero-mark\">561</p><p class=\"hero-desc\">Autonomous Confederacy</p></div></header>\n<main id=\"main-content\" role=\"main\">\n<article class=\"h-entry\"><span class=\"p-name\">The 561 Group</span><a class=\"u-url\" href=\"https://561.group/home\">https://561.group/home</a><span class=\"p-summary\">An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.</span><div class=\"e-content\">  <article class=\"semantic-hypertext-packet\" data-subject=\"home\" data-cells=\"4\" data-mode=\"calm\">\n    <section class=\"subject\" data-e=\"home\">\n      <span class=\"title\" data-e=\"home\" data-a=\"title\" data-v=\"The 561 Group\">title The 561 Group</span>\n      <span class=\"type\" data-e=\"home\" data-a=\"type\" data-v=\"index\">type index</span>\n      <span class=\"summary\" data-e=\"home\" data-a=\"summary\" data-v=\"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\">summary An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.</span>\n      <span class=\"status\" data-e=\"home\" data-a=\"status\" data-v=\"published\">status published</span>\n    </section>\n  </article><p>The 561 Group is the public facade of a Union of independent enterprises that research, design, and operate technical infrastructure for long-horizon autonomy, collective intelligence, Black Liberation, Indigenous Sovereignty, and strategic prosperity.</p>\n<p>We publish reusable knowledge and source code under the <a href=\"https://github.com/561-group\">561-group GitHub organization</a>. We operate and sell the scarce work that makes it reliable in the world: paid nodes, measured execution, integration, assurance, and support. Open source is the common layer on which accountable services compete.</p>\n<h2>Services</h2>\n<p><a href=\"https://market.561.group/\">Market.561.group</a> is our commercial catalog. Each offer identifies its owning enterprise, public source, endpoint, price, chain policy, and evidence status. The first qualified product line pairs the Apache-2.0 x402 boundary reference with the separately operated Paid Ephemeris Gateway: free source for anyone to inspect and run, and a pay-to-use node for customers who want operated measurement, provenance, and a settlement-recording boundary.</p>\n<h2>What&#39;s running right now</h2>\n<p>Underneath the market listing is a live work-order loop: demand is minted directly from operator speech and from a capability registry, then dispatched every few minutes to whichever admitted inference provider — a hosted model or the operator&#39;s own hardware — can fulfill it most cheaply. Each dispatch is a receipted, typed exchange: input in, output or a named refusal out, never a silent mutation. This is the same machinery drafting glossary definitions, service designs, and new paid-product proposals elsewhere in this Union — an operating loop, not a demo.</p>\n<h2>Sponsor the work</h2>\n<p>Sponsorship funds public research, mathematical publications, documentation, independent verification, and operating capacity. It is support for a public commons, not hidden access or control over a sovereign enterprise&#39;s findings. The market carries the published sponsorship terms and recipient policy. The current route accepts Base USDC (<code>eip155:8453</code>) at <code>0x42F72C0a340A4A55C082Fe42483e87691D2bff64</code>; it is a sponsorship transfer, not payment for a service response.</p>\n<h2>Web-borne Union</h2>\n<p>The 561 Group is the first public realization of the Union&#39;s operating model: enterprises publish their own source and offers, customers choose them through explicit contracts, x402 settles paid HTTP crossings, and each enterprise keeps its own evidence. The apex makes the federation legible; it does not turn the federation into a single ambient platform.</p>\n<p><a href=\"https://koios.news/\">Koios News</a> is a sibling public enterprise in the same federation, publishing independently under its own name and source.</p></div></article>\n</main>\n<footer role=\"contentinfo\"><div class=\"colophon\"><span>2026 · The 561 Group</span></div></footer>\n</body>\n</html>\n","/index.html":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>The 561 Group</title>\n    <meta name=\"description\" content=\"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\" />\n    <meta name=\"generator\" content=\"@red-cup-engineering/web-theming theme=five-six-one\" />\n    <link rel=\"canonical\" href=\"https://561.group/\" />\n    <style>:root {\n  --ink: #0A0A0A;\n  --ink-soft: #494742;\n  --surface: #F2EAD8;\n  --surface-deep: #e2daca;\n  --surface-edge: #c7c1b2;\n  --rule: #cdc6b7;\n  --tint: #e4ddcc;\n  --tint-strong: #d4cebe;\n  --selection: #9ca5b6;\n  --accent: #3D5588;\n  --alarm: #FF4530;\n  --visited: #2a3958;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n@media (prefers-color-scheme: dark) {\n:root {\n  --ink: #e4e4e4;\n  --ink-soft: #999791;\n  --surface: #120c02;\n  --surface-deep: #1c160a;\n  --surface-edge: #2e281d;\n  --rule: #2a2519;\n  --tint: #1a1408;\n  --tint-strong: #251f13;\n  --selection: #434b59;\n  --accent: #88a4dd;\n  --alarm: #ff4530;\n  --visited: #a8bbe0;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n}\n[data-theme=\"light\"] {\n  --ink: #0A0A0A;\n  --ink-soft: #494742;\n  --surface: #F2EAD8;\n  --surface-deep: #e2daca;\n  --surface-edge: #c7c1b2;\n  --rule: #cdc6b7;\n  --tint: #e4ddcc;\n  --tint-strong: #d4cebe;\n  --selection: #9ca5b6;\n  --accent: #3D5588;\n  --alarm: #FF4530;\n  --visited: #2a3958;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n[data-theme=\"dark\"] {\n  --ink: #e4e4e4;\n  --ink-soft: #999791;\n  --surface: #120c02;\n  --surface-deep: #1c160a;\n  --surface-edge: #2e281d;\n  --rule: #2a2519;\n  --tint: #1a1408;\n  --tint-strong: #251f13;\n  --selection: #434b59;\n  --accent: #88a4dd;\n  --alarm: #ff4530;\n  --visited: #a8bbe0;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}\nhtml{color-scheme:light dark;-webkit-text-size-adjust:100%;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}\nbody{background:var(--surface);color:var(--ink);line-height:1.55;overflow-wrap:break-word;hyphens:auto}\nimg{max-width:100%;height:auto;display:block}\na{color:var(--accent)}\na:visited{color:var(--visited,var(--accent))}\n::selection{background:var(--selection,var(--accent));color:var(--surface)}\n\n/* Headings — type as mass: display face, tight, load-bearing. */\nh1,h2,h3,h4,h5,h6{font-family:var(--sans);font-weight:700;line-height:1.1;letter-spacing:-.02em;text-wrap:balance;overflow-wrap:break-word}\nh1{font-size:clamp(1.9rem,5vw,2.8rem);margin:0 0 .5rem}\nh2{font-size:clamp(1.35rem,3vw,1.8rem);margin:2rem 0 .6rem;padding-top:.6rem;border-top:1px solid var(--rule)}\nh3{font-size:1.2rem;margin:1.5rem 0 .4rem}\nh4{font-size:1rem;margin:1.2rem 0 .3rem}\np{text-wrap:pretty}\n\n/* Prose — the default styled content block. */\n.prose{font-family:var(--serif);font-size:1.0625rem;line-height:1.6;max-width:var(--measure,42rem)}\n.prose>*+*{margin-top:1.1rem}\n.prose a{color:var(--accent);text-underline-offset:2px}\n.prose strong{font-weight:700}\n.prose em{font-style:italic}\n.prose ul,.prose ol{padding-left:1.4rem}\n.prose li+li{margin-top:.3rem}\n.prose hr{border:0;border-top:2px solid var(--rule);margin:2rem 0}\n\n/* Lede — opening paragraph. */\n.lede{font-family:var(--serif);font-size:clamp(1.1rem,1.6vw,1.3rem);line-height:1.45;color:var(--ink)}\n\n/* Figures. */\nfigure{margin:1.6rem 0}\nfigcaption{font-family:var(--mono);font-size:.78rem;color:var(--ink-soft);margin-top:.4rem}\n\n/* Code. */\ncode{font-family:var(--mono);font-size:.88em;background:var(--surface-deep);padding:.1em .35em;border-radius:var(--radius,.25rem)}\npre{font-family:var(--mono);font-size:.85rem;background:var(--surface-deep);border:1px solid var(--surface-edge);padding:1rem;overflow-x:auto;border-radius:var(--radius,.25rem)}\npre code{background:none;padding:0}\n\n/* Blockquote + callout. */\nblockquote{margin:1.4rem 0;padding:.5rem 0 .5rem 1.2rem;border-left:3px solid var(--accent);font-style:italic;color:var(--ink-soft)}\n.callout{background:var(--tint,var(--surface-deep));border-left:3px solid var(--accent);padding:.9rem 1.1rem;margin:1.4rem 0}\n\n/* Held contradiction — the display state mainstream theming kits structurally\n   lack, because none sit on a paraconsistent substrate. A cell our logic holds\n   as both-witnessed-and-obstructed is SHOWN, never silently resolved (Cubist\n   anti-closure: sustain the reading rather than collapse it). Anti-closure with\n   rails: it is always visible (Tuftean integrity — contradiction is never\n   hidden) yet restrained by default (Brutalist salience scarcity — not every\n   mark shouts). [data-mode=audit] amplifies it into a salient block; calm mode\n   keeps it a quiet underline. Themeable via --alarm; no new token names. */\n[data-contested=true]{text-decoration:underline dotted var(--alarm,#c33);text-decoration-thickness:2px;text-underline-offset:2px;cursor:help}\n[data-mode=calm] [data-contested=true]{text-decoration-style:dotted}\n[data-mode=audit] [data-contested=true]{background:color-mix(in oklab,var(--alarm,#c33) 12%,transparent);outline:1px solid var(--alarm,#c33);padding:0 .15em;border-radius:var(--radius,0)}\n.contested-strip{font-family:var(--mono);font-size:.8rem;color:var(--alarm,#c33);background:color-mix(in oklab,var(--alarm,#c33) 8%,transparent);border:1px solid var(--alarm,#c33);padding:.5rem .7rem;margin:.6rem 0;border-radius:var(--radius,0);white-space:pre-line}\n/* Honest absence — a gap is rendered, not left blank (Tuftean integrity). */\n.gap,[data-gap=true]{font-family:var(--mono);font-size:.85em;font-style:italic;color:var(--ink-soft)}\n\n/* Card grid + cards. */\n.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(15rem,1fr));gap:1rem;margin:1.4rem 0}\n.card{background:var(--surface-deep);border:1px solid var(--surface-edge);padding:1.1rem 1.2rem;border-radius:var(--radius,0)}\na.card{display:block;text-decoration:none;color:inherit;transition:border-color .12s}\na.card:hover{border-color:var(--accent)}\n.card__title{font-family:var(--sans);font-weight:700;font-size:1.15rem;letter-spacing:-.02em}\n.card__meta{font-family:var(--mono);font-size:.72rem;text-transform:uppercase;letter-spacing:.08em;color:var(--ink-soft)}\n\n/* Feed / list of entries (h-feed). */\n.h-feed,.feed{list-style:none;padding:0;margin:0}\n.h-feed>li,.feed>li{padding:1rem 0;border-bottom:1px solid var(--rule)}\n.feed__title{font-family:var(--sans);font-weight:700;font-size:1.2rem}\n.feed__sum{color:var(--ink-soft);margin-top:.3rem;max-width:60ch}\n\n/* Breadcrumbs. */\n.breadcrumbs{font-family:var(--mono);font-size:.72rem;letter-spacing:.04em;color:var(--ink-soft);margin-bottom:.6rem}\n.breadcrumbs a{color:var(--ink-soft)}\n.breadcrumb-sep{margin:0 .35em;color:var(--surface-edge)}\n\n/* Table of contents. */\n.toc{border:1px solid var(--surface-edge);background:var(--surface-deep);padding:.8rem 1rem;margin:1.4rem 0}\n.toc summary{font-family:var(--mono);font-size:.74rem;text-transform:uppercase;letter-spacing:.1em;color:var(--ink-soft);cursor:pointer}\n.toc ul{list-style:none;padding-left:1rem;margin:.4rem 0 0}\n.toc a{font-family:var(--mono);font-size:.82rem;color:var(--ink-soft)}\n.toc a:hover{color:var(--ink)}\n\n/* Tags. */\n.tags{display:flex;flex-wrap:wrap;gap:.35rem;margin:1rem 0}\n.tag,.tags a,.p-category{display:inline-block;font-family:var(--mono);font-size:.72rem;text-transform:uppercase;letter-spacing:.06em;text-decoration:none;border:1px solid var(--surface-edge);padding:.15em .5em;color:var(--ink-soft)}\n.tag:hover,.tags a:hover,a.p-category:hover{background:var(--ink);color:var(--surface)}\n\n/* Tables. */\ntable{border-collapse:collapse;width:100%;margin:1.4rem 0;font-size:.95em}\nth,td{padding:.4em .7em;border:1px solid var(--rule);text-align:left}\nthead th{font-family:var(--mono);font-size:.78rem;text-transform:uppercase;letter-spacing:.06em;background:var(--surface-deep)}\n\n/* Pagination. */\n.pagination{display:flex;gap:1rem;justify-content:space-between;font-family:var(--mono);font-size:.8rem;margin:2rem 0;padding-top:1rem;border-top:1px solid var(--rule)}\n\n/* Forms. */\ninput,button,textarea,select{font-family:var(--sans);font-size:.9rem;color:var(--ink);background:var(--surface);border:1.5px solid var(--surface-edge);padding:.4rem .6rem;border-radius:var(--radius,0)}\nbutton{font-weight:700;cursor:pointer}\nbutton:hover{background:var(--ink);color:var(--surface)}\n\n/* Accessibility. */\n.skip-to-content{position:absolute;left:-9999px}\n.skip-to-content:focus{position:static}\n\n\nhtml, body {\n  background: var(--surface);\n  font-family: var(--serif);\n  font-size: 16px;\n}\nbody {\n  background-image: radial-gradient(rgba(10,10,10,.035) 1px, transparent 1px);\n  background-size: 4px 4px;\n  min-height: 100dvh;\n  display: flex;\n  flex-direction: column;\n}\n\n/* ── Header: folio bar + hero mark ───────────────────────────────────────── */\n\nheader[role=banner] {\n  max-width: var(--max);\n  width: 100%;\n  margin: 0 auto;\n  padding: 0 var(--gutter);\n}\n\n.folio-bar {\n  border-top: 8px solid var(--ink);\n  border-bottom: 1px solid var(--ink);\n  padding: 10px 0;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-family: var(--mono);\n  font-size: 11px;\n  line-height: 1.4;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: var(--ink-soft);\n}\n\n.hero {\n  padding: 80px 0 56px;\n  border-bottom: 1px solid var(--ink);\n}\n\n.hero-mark {\n  font-family: var(--sans);\n  font-weight: 700;\n  font-size: clamp(72px, 14vw, 128px);\n  line-height: .85;\n  letter-spacing: -.04em;\n}\n\n.hero-desc {\n  margin-top: 20px;\n  font-family: var(--mono);\n  font-size: 11px;\n  line-height: 1.4;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: var(--ink-soft);\n}\n\n/* ── Main content ────────────────────────────────────────────────────────── */\n\nmain[role=main] {\n  flex: 1;\n  max-width: var(--max);\n  width: 100%;\n  margin: 0 auto;\n  padding: 60px var(--gutter);\n}\n\n/* ── Footer colophon ─────────────────────────────────────────────────────── */\n\nfooter[role=contentinfo] {\n  border-top: 8px solid var(--ink);\n  background: var(--ink);\n  color: var(--surface);\n}\n\n.colophon {\n  max-width: var(--max);\n  margin: 0 auto;\n  padding: 32px var(--gutter);\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-family: var(--mono);\n  font-size: 11px;\n  line-height: 1.4;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: color-mix(in oklab, var(--surface) 60%, transparent);\n}\n\n.colophon a { color: var(--surface); text-decoration: none; }\n.colophon a:hover { color: var(--alarm); }\n\n/* ── Responsive ──────────────────────────────────────────────────────────── */\n\n@media (max-width: 880px) {\n  :root { --gutter: 24px; }\n  .hero { padding: 48px 0 36px; }\n  main[role=main] { padding: 40px var(--gutter); }\n  .colophon { flex-direction: column; gap: 12px; align-items: flex-start; }\n}\n\n@media print {\n  body { background: none; background-image: none; }\n  footer[role=contentinfo] { background: none; color: var(--ink); border-top-color: var(--ink); }\n  .folio-bar, .hero-desc, .colophon { color: #333; }\n}\n</style>\n    <link rel=\"alternate\" type=\"application/json\" href=\"/site.json\">\n    <link rel=\"alternate\" type=\"application/feed+json\" href=\"https://561.group/feed.json\" title=\"The 561 Group JSON Feed\" />\n    <link rel=\"alternate\" type=\"application/atom+xml\" href=\"https://561.group/feed.atom\" title=\"The 561 Group Atom\" />\n    <link rel=\"alternate\" type=\"application/rss+xml\" href=\"https://561.group/feed.xml\" title=\"The 561 Group RSS\" />\n    <script type=\"application/ld+json\">{\n  \"@context\": \"https://schema.org\",\n  \"@type\": [\n    \"WebSite\",\n    \"CollectionPage\"\n  ],\n  \"@id\": \"https://561.group/#site\",\n  \"name\": \"The 561 Group\",\n  \"url\": \"https://561.group/\",\n  \"description\": \"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\",\n  \"inLanguage\": \"en\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"CreativeWork\",\n      \"@id\": \"https://561.group/home\",\n      \"url\": \"https://561.group/home\",\n      \"name\": \"The 561 Group\"\n    },\n    {\n      \"@type\": \"CreativeWork\",\n      \"@id\": \"https://561.group/market\",\n      \"url\": \"https://561.group/market\",\n      \"name\": \"561 Group Market\"\n    }\n  ]\n}</script>\n</head>\n<body class=\"theme-five-six-one\">\n<header role=\"banner\"><div class=\"folio-bar\"><span>The 561 Group</span><span>561.GROUP</span></div><div class=\"hero\"><p class=\"hero-mark\">561</p><p class=\"hero-desc\">Autonomous Confederacy</p></div></header>\n<main id=\"main-content\" role=\"main\">\n  <article class=\"semantic-hypertext-packet\" data-subject=\"home\" data-cells=\"4\" data-mode=\"calm\">\n    <section class=\"subject\" data-e=\"home\">\n      <span class=\"title\" data-e=\"home\" data-a=\"title\" data-v=\"The 561 Group\">title The 561 Group</span>\n      <span class=\"type\" data-e=\"home\" data-a=\"type\" data-v=\"index\">type index</span>\n      <span class=\"summary\" data-e=\"home\" data-a=\"summary\" data-v=\"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\">summary An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.</span>\n      <span class=\"status\" data-e=\"home\" data-a=\"status\" data-v=\"published\">status published</span>\n    </section>\n  </article><p>The 561 Group is the public facade of a Union of independent enterprises that research, design, and operate technical infrastructure for long-horizon autonomy, collective intelligence, Black Liberation, Indigenous Sovereignty, and strategic prosperity.</p>\n<p>We publish reusable knowledge and source code under the <a href=\"https://github.com/561-group\">561-group GitHub organization</a>. We operate and sell the scarce work that makes it reliable in the world: paid nodes, measured execution, integration, assurance, and support. Open source is the common layer on which accountable services compete.</p>\n<h2>Services</h2>\n<p><a href=\"https://market.561.group/\">Market.561.group</a> is our commercial catalog. Each offer identifies its owning enterprise, public source, endpoint, price, chain policy, and evidence status. The first qualified product line pairs the Apache-2.0 x402 boundary reference with the separately operated Paid Ephemeris Gateway: free source for anyone to inspect and run, and a pay-to-use node for customers who want operated measurement, provenance, and a settlement-recording boundary.</p>\n<h2>What&#39;s running right now</h2>\n<p>Underneath the market listing is a live work-order loop: demand is minted directly from operator speech and from a capability registry, then dispatched every few minutes to whichever admitted inference provider — a hosted model or the operator&#39;s own hardware — can fulfill it most cheaply. Each dispatch is a receipted, typed exchange: input in, output or a named refusal out, never a silent mutation. This is the same machinery drafting glossary definitions, service designs, and new paid-product proposals elsewhere in this Union — an operating loop, not a demo.</p>\n<h2>Sponsor the work</h2>\n<p>Sponsorship funds public research, mathematical publications, documentation, independent verification, and operating capacity. It is support for a public commons, not hidden access or control over a sovereign enterprise&#39;s findings. The market carries the published sponsorship terms and recipient policy. The current route accepts Base USDC (<code>eip155:8453</code>) at <code>0x42F72C0a340A4A55C082Fe42483e87691D2bff64</code>; it is a sponsorship transfer, not payment for a service response.</p>\n<h2>Web-borne Union</h2>\n<p>The 561 Group is the first public realization of the Union&#39;s operating model: enterprises publish their own source and offers, customers choose them through explicit contracts, x402 settles paid HTTP crossings, and each enterprise keeps its own evidence. The apex makes the federation legible; it does not turn the federation into a single ambient platform.</p>\n<p><a href=\"https://koios.news/\">Koios News</a> is a sibling public enterprise in the same federation, publishing independently under its own name and source.</p>\n</main>\n<footer role=\"contentinfo\"><div class=\"colophon\"><span>2026 · The 561 Group</span></div></footer>\n</body>\n</html>\n","/market.jsonld":"{\n  \"@context\": [\n    \"https://schema.org\",\n    {\n      \"skos\": \"http://www.w3.org/2004/02/skos/core#\",\n      \"ws\": \"https://561.group/vocab#\",\n      \"prov\": \"http://www.w3.org/ns/prov#\"\n    }\n  ],\n  \"@id\": \"https://561.group/market\",\n  \"@type\": \"Article\",\n  \"name\": \"561 Group Market\",\n  \"url\": \"https://561.group/market\",\n  \"description\": \"Open source, operated services, and sponsorship.\",\n  \"dateModified\": \"2026-07-29T19:56:26.820Z\",\n  \"publisher\": {\n    \"@type\": \"Organization\",\n    \"name\": \"The 561 Group\",\n    \"url\": \"https://561.group\"\n  },\n  \"ws:claims\": {\n    \"potential\": [\n      {\n        \"predicate\": \"title\",\n        \"object\": \"561 Group Market\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/market.md\"\n      },\n      {\n        \"predicate\": \"type\",\n        \"object\": \"page\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/market.md\"\n      },\n      {\n        \"predicate\": \"summary\",\n        \"object\": \"Open source, operated services, and sponsorship.\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/market.md\"\n      },\n      {\n        \"predicate\": \"status\",\n        \"object\": \"published\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/market.md\"\n      },\n      {\n        \"predicate\": \"body\",\n        \"object\": \"The 561 Group Market is a catalog of independent enterprises, not a platform\\nthat takes custody of them. Every offer identifies the enterprise that owns\\nthe boundary, public source, operational endpoint, price, chain/payee policy,\\nand evidence through which a customer can check the claim.\\n\\n## Paid Ephemeris Gateway — live on Base\\n\\n**Owner:** RSC Quiescent / paid-ephemeris-gateway  \\n**Health:** [live status](https://ephemeris.561.group/v1/status)  \\n**Purchase route:** `GET https://ephemeris.561.group/v1/ephemeris/moment/:date`  \\n**Settlement:** x402 v2 exact on Base (`eip155:8453`) in USDC  \\n**Moment Essentials:** $0.04 USDC  \\n**Precision Moment:** $0.32 USDC with observer location.\\n\\nThe endpoint's own `402 Payment Required` challenge is authoritative for its\\ncurrent asset, payee, and price. The catalog requalifies that public challenge\\nevery six hours without attempting payment or settlement.\\n\\n## Open x402 boundary source\\n\\nThe Apache-2.0\\n[x402 Boundary Reference](https://github.com/561-group/x402-boundary-reference)\\nis the paired public implementation for studying, running, and independently\\nchecking an explicit x402 v2 boundary. Customers may use the source freely or\\nbuy the separately operated Ephemeris service when they value its operation,\\nmeasurement provenance, and evidence trail.\\n\\n## Sponsorship\\n\\nSponsorship funds public mathematics, protocol references, documentation,\\nassays, verification, and resilient operations. It does not purchase hidden\\naccess, custody, or control of research conclusions. The current public route\\naccepts Base USDC on `eip155:8453` at\\n`0x42F72C0a340A4A55C082Fe42483e87691D2bff64`. A sponsorship transfer is not a\\npayment for an Ephemeris response or a claim on customer receipts.\\n\\n## Listing rule\\n\\nEvery paid listing must be independently checkable against its public HTTPS\\nx402 challenge and signed provider identity. The market publishes the offer;\\nthe owning enterprise settles and records the transaction.\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/market.md\"\n      }\n    ],\n    \"active\": [],\n    \"stable\": []\n  }\n}\n","/market.ttl":"@prefix dc: <http://purl.org/dc/terms/> .\n@prefix owl: <http://www.w3.org/2002/07/owl#> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\n@prefix schema: <https://schema.org/> .\n@prefix skos: <http://www.w3.org/2004/02/skos/core#> .\n@prefix ws: <https://561.group/vocab#> .\n<https://561.group/market> a schema:Article, ws:Subject ;\n  schema:url <https://561.group/market> ;\n  schema:identifier <https://561.group/market> .\n<https://561.group/market> schema:name \"561 Group Market\" .\n<https://561.group/market> dc:type \"page\" .\n<https://561.group/market> schema:abstract \"Open source, operated services, and sponsorship.\" .\n<https://561.group/market> ws:status \"published\" .\n<https://561.group/market> ws:body \"The 561 Group Market is a catalog of independent enterprises, not a platform\nthat takes custody of them. Every offer identifies the enterprise that owns\nthe boundary, public source, operational endpoint, price, chain/payee policy,\nand evidence through which a customer can check the claim.\n\n## Paid Ephemeris Gateway — live on Base\n\n**Owner:** RSC Quiescent / paid-ephemeris-gateway  \n**Health:** [live status](https://ephemeris.561.group/v1/status)  \n**Purchase route:** `GET https://ephemeris.561.group/v1/ephemeris/moment/:date`  \n**Settlement:** x402 v2 exact on Base (`eip155:8453`) in USDC  \n**Moment Essentials:** $0.04 USDC  \n**Precision Moment:** $0.32 USDC with observer location.\n\nThe endpoint's own `402 Payment Required` challenge is authoritative for its\ncurrent asset, payee, and price. The catalog requalifies that public challenge\nevery six hours without attempting payment or settlement.\n\n## Open x402 boundary source\n\nThe Apache-2.0\n[x402 Boundary Reference](https://github.com/561-group/x402-boundary-reference)\nis the paired public implementation for studying, running, and independently\nchecking an explicit x402 v2 boundary. Customers may use the source freely or\nbuy the separately operated Ephemeris service when they value its operation,\nmeasurement provenance, and evidence trail.\n\n## Sponsorship\n\nSponsorship funds public mathematics, protocol references, documentation,\nassays, verification, and resilient operations. It does not purchase hidden\naccess, custody, or control of research conclusions. The current public route\naccepts Base USDC on `eip155:8453` at\n`0x42F72C0a340A4A55C082Fe42483e87691D2bff64`. A sponsorship transfer is not a\npayment for an Ephemeris response or a claim on customer receipts.\n\n## Listing rule\n\nEvery paid listing must be independently checkable against its public HTTPS\nx402 challenge and signed provider identity. The market publishes the offer;\nthe owning enterprise settles and records the transaction.\" .\n","/market/index.html":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <title>561 Group Market</title>\n    <meta name=\"description\" content=\"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\" />\n    <meta name=\"generator\" content=\"@red-cup-engineering/web-theming theme=five-six-one\" />\n    <link rel=\"canonical\" href=\"https://561.group/market\" />\n    <style>:root {\n  --ink: #0A0A0A;\n  --ink-soft: #494742;\n  --surface: #F2EAD8;\n  --surface-deep: #e2daca;\n  --surface-edge: #c7c1b2;\n  --rule: #cdc6b7;\n  --tint: #e4ddcc;\n  --tint-strong: #d4cebe;\n  --selection: #9ca5b6;\n  --accent: #3D5588;\n  --alarm: #FF4530;\n  --visited: #2a3958;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n@media (prefers-color-scheme: dark) {\n:root {\n  --ink: #e4e4e4;\n  --ink-soft: #999791;\n  --surface: #120c02;\n  --surface-deep: #1c160a;\n  --surface-edge: #2e281d;\n  --rule: #2a2519;\n  --tint: #1a1408;\n  --tint-strong: #251f13;\n  --selection: #434b59;\n  --accent: #88a4dd;\n  --alarm: #ff4530;\n  --visited: #a8bbe0;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n}\n[data-theme=\"light\"] {\n  --ink: #0A0A0A;\n  --ink-soft: #494742;\n  --surface: #F2EAD8;\n  --surface-deep: #e2daca;\n  --surface-edge: #c7c1b2;\n  --rule: #cdc6b7;\n  --tint: #e4ddcc;\n  --tint-strong: #d4cebe;\n  --selection: #9ca5b6;\n  --accent: #3D5588;\n  --alarm: #FF4530;\n  --visited: #2a3958;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n[data-theme=\"dark\"] {\n  --ink: #e4e4e4;\n  --ink-soft: #999791;\n  --surface: #120c02;\n  --surface-deep: #1c160a;\n  --surface-edge: #2e281d;\n  --rule: #2a2519;\n  --tint: #1a1408;\n  --tint-strong: #251f13;\n  --selection: #434b59;\n  --accent: #88a4dd;\n  --alarm: #ff4530;\n  --visited: #a8bbe0;\n  --sans: \"Space Grotesk\", \"Helvetica Neue\", Arial, sans-serif;\n  --serif: \"Roboto Slab\", Rockwell, Georgia, serif;\n  --mono: \"JetBrains Mono\", ui-monospace, \"Courier New\", monospace;\n  --gutter: 56px;\n  --max: 1200px;\n  --measure: 42rem;\n  --radius: 0;\n}\n\n*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}\nhtml{color-scheme:light dark;-webkit-text-size-adjust:100%;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}\nbody{background:var(--surface);color:var(--ink);line-height:1.55;overflow-wrap:break-word;hyphens:auto}\nimg{max-width:100%;height:auto;display:block}\na{color:var(--accent)}\na:visited{color:var(--visited,var(--accent))}\n::selection{background:var(--selection,var(--accent));color:var(--surface)}\n\n/* Headings — type as mass: display face, tight, load-bearing. */\nh1,h2,h3,h4,h5,h6{font-family:var(--sans);font-weight:700;line-height:1.1;letter-spacing:-.02em;text-wrap:balance;overflow-wrap:break-word}\nh1{font-size:clamp(1.9rem,5vw,2.8rem);margin:0 0 .5rem}\nh2{font-size:clamp(1.35rem,3vw,1.8rem);margin:2rem 0 .6rem;padding-top:.6rem;border-top:1px solid var(--rule)}\nh3{font-size:1.2rem;margin:1.5rem 0 .4rem}\nh4{font-size:1rem;margin:1.2rem 0 .3rem}\np{text-wrap:pretty}\n\n/* Prose — the default styled content block. */\n.prose{font-family:var(--serif);font-size:1.0625rem;line-height:1.6;max-width:var(--measure,42rem)}\n.prose>*+*{margin-top:1.1rem}\n.prose a{color:var(--accent);text-underline-offset:2px}\n.prose strong{font-weight:700}\n.prose em{font-style:italic}\n.prose ul,.prose ol{padding-left:1.4rem}\n.prose li+li{margin-top:.3rem}\n.prose hr{border:0;border-top:2px solid var(--rule);margin:2rem 0}\n\n/* Lede — opening paragraph. */\n.lede{font-family:var(--serif);font-size:clamp(1.1rem,1.6vw,1.3rem);line-height:1.45;color:var(--ink)}\n\n/* Figures. */\nfigure{margin:1.6rem 0}\nfigcaption{font-family:var(--mono);font-size:.78rem;color:var(--ink-soft);margin-top:.4rem}\n\n/* Code. */\ncode{font-family:var(--mono);font-size:.88em;background:var(--surface-deep);padding:.1em .35em;border-radius:var(--radius,.25rem)}\npre{font-family:var(--mono);font-size:.85rem;background:var(--surface-deep);border:1px solid var(--surface-edge);padding:1rem;overflow-x:auto;border-radius:var(--radius,.25rem)}\npre code{background:none;padding:0}\n\n/* Blockquote + callout. */\nblockquote{margin:1.4rem 0;padding:.5rem 0 .5rem 1.2rem;border-left:3px solid var(--accent);font-style:italic;color:var(--ink-soft)}\n.callout{background:var(--tint,var(--surface-deep));border-left:3px solid var(--accent);padding:.9rem 1.1rem;margin:1.4rem 0}\n\n/* Held contradiction — the display state mainstream theming kits structurally\n   lack, because none sit on a paraconsistent substrate. A cell our logic holds\n   as both-witnessed-and-obstructed is SHOWN, never silently resolved (Cubist\n   anti-closure: sustain the reading rather than collapse it). Anti-closure with\n   rails: it is always visible (Tuftean integrity — contradiction is never\n   hidden) yet restrained by default (Brutalist salience scarcity — not every\n   mark shouts). [data-mode=audit] amplifies it into a salient block; calm mode\n   keeps it a quiet underline. Themeable via --alarm; no new token names. */\n[data-contested=true]{text-decoration:underline dotted var(--alarm,#c33);text-decoration-thickness:2px;text-underline-offset:2px;cursor:help}\n[data-mode=calm] [data-contested=true]{text-decoration-style:dotted}\n[data-mode=audit] [data-contested=true]{background:color-mix(in oklab,var(--alarm,#c33) 12%,transparent);outline:1px solid var(--alarm,#c33);padding:0 .15em;border-radius:var(--radius,0)}\n.contested-strip{font-family:var(--mono);font-size:.8rem;color:var(--alarm,#c33);background:color-mix(in oklab,var(--alarm,#c33) 8%,transparent);border:1px solid var(--alarm,#c33);padding:.5rem .7rem;margin:.6rem 0;border-radius:var(--radius,0);white-space:pre-line}\n/* Honest absence — a gap is rendered, not left blank (Tuftean integrity). */\n.gap,[data-gap=true]{font-family:var(--mono);font-size:.85em;font-style:italic;color:var(--ink-soft)}\n\n/* Card grid + cards. */\n.card-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(15rem,1fr));gap:1rem;margin:1.4rem 0}\n.card{background:var(--surface-deep);border:1px solid var(--surface-edge);padding:1.1rem 1.2rem;border-radius:var(--radius,0)}\na.card{display:block;text-decoration:none;color:inherit;transition:border-color .12s}\na.card:hover{border-color:var(--accent)}\n.card__title{font-family:var(--sans);font-weight:700;font-size:1.15rem;letter-spacing:-.02em}\n.card__meta{font-family:var(--mono);font-size:.72rem;text-transform:uppercase;letter-spacing:.08em;color:var(--ink-soft)}\n\n/* Feed / list of entries (h-feed). */\n.h-feed,.feed{list-style:none;padding:0;margin:0}\n.h-feed>li,.feed>li{padding:1rem 0;border-bottom:1px solid var(--rule)}\n.feed__title{font-family:var(--sans);font-weight:700;font-size:1.2rem}\n.feed__sum{color:var(--ink-soft);margin-top:.3rem;max-width:60ch}\n\n/* Breadcrumbs. */\n.breadcrumbs{font-family:var(--mono);font-size:.72rem;letter-spacing:.04em;color:var(--ink-soft);margin-bottom:.6rem}\n.breadcrumbs a{color:var(--ink-soft)}\n.breadcrumb-sep{margin:0 .35em;color:var(--surface-edge)}\n\n/* Table of contents. */\n.toc{border:1px solid var(--surface-edge);background:var(--surface-deep);padding:.8rem 1rem;margin:1.4rem 0}\n.toc summary{font-family:var(--mono);font-size:.74rem;text-transform:uppercase;letter-spacing:.1em;color:var(--ink-soft);cursor:pointer}\n.toc ul{list-style:none;padding-left:1rem;margin:.4rem 0 0}\n.toc a{font-family:var(--mono);font-size:.82rem;color:var(--ink-soft)}\n.toc a:hover{color:var(--ink)}\n\n/* Tags. */\n.tags{display:flex;flex-wrap:wrap;gap:.35rem;margin:1rem 0}\n.tag,.tags a,.p-category{display:inline-block;font-family:var(--mono);font-size:.72rem;text-transform:uppercase;letter-spacing:.06em;text-decoration:none;border:1px solid var(--surface-edge);padding:.15em .5em;color:var(--ink-soft)}\n.tag:hover,.tags a:hover,a.p-category:hover{background:var(--ink);color:var(--surface)}\n\n/* Tables. */\ntable{border-collapse:collapse;width:100%;margin:1.4rem 0;font-size:.95em}\nth,td{padding:.4em .7em;border:1px solid var(--rule);text-align:left}\nthead th{font-family:var(--mono);font-size:.78rem;text-transform:uppercase;letter-spacing:.06em;background:var(--surface-deep)}\n\n/* Pagination. */\n.pagination{display:flex;gap:1rem;justify-content:space-between;font-family:var(--mono);font-size:.8rem;margin:2rem 0;padding-top:1rem;border-top:1px solid var(--rule)}\n\n/* Forms. */\ninput,button,textarea,select{font-family:var(--sans);font-size:.9rem;color:var(--ink);background:var(--surface);border:1.5px solid var(--surface-edge);padding:.4rem .6rem;border-radius:var(--radius,0)}\nbutton{font-weight:700;cursor:pointer}\nbutton:hover{background:var(--ink);color:var(--surface)}\n\n/* Accessibility. */\n.skip-to-content{position:absolute;left:-9999px}\n.skip-to-content:focus{position:static}\n\n\nhtml, body {\n  background: var(--surface);\n  font-family: var(--serif);\n  font-size: 16px;\n}\nbody {\n  background-image: radial-gradient(rgba(10,10,10,.035) 1px, transparent 1px);\n  background-size: 4px 4px;\n  min-height: 100dvh;\n  display: flex;\n  flex-direction: column;\n}\n\n/* ── Header: folio bar + hero mark ───────────────────────────────────────── */\n\nheader[role=banner] {\n  max-width: var(--max);\n  width: 100%;\n  margin: 0 auto;\n  padding: 0 var(--gutter);\n}\n\n.folio-bar {\n  border-top: 8px solid var(--ink);\n  border-bottom: 1px solid var(--ink);\n  padding: 10px 0;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-family: var(--mono);\n  font-size: 11px;\n  line-height: 1.4;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: var(--ink-soft);\n}\n\n.hero {\n  padding: 80px 0 56px;\n  border-bottom: 1px solid var(--ink);\n}\n\n.hero-mark {\n  font-family: var(--sans);\n  font-weight: 700;\n  font-size: clamp(72px, 14vw, 128px);\n  line-height: .85;\n  letter-spacing: -.04em;\n}\n\n.hero-desc {\n  margin-top: 20px;\n  font-family: var(--mono);\n  font-size: 11px;\n  line-height: 1.4;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: var(--ink-soft);\n}\n\n/* ── Main content ────────────────────────────────────────────────────────── */\n\nmain[role=main] {\n  flex: 1;\n  max-width: var(--max);\n  width: 100%;\n  margin: 0 auto;\n  padding: 60px var(--gutter);\n}\n\n/* ── Footer colophon ─────────────────────────────────────────────────────── */\n\nfooter[role=contentinfo] {\n  border-top: 8px solid var(--ink);\n  background: var(--ink);\n  color: var(--surface);\n}\n\n.colophon {\n  max-width: var(--max);\n  margin: 0 auto;\n  padding: 32px var(--gutter);\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  font-family: var(--mono);\n  font-size: 11px;\n  line-height: 1.4;\n  letter-spacing: .18em;\n  text-transform: uppercase;\n  color: color-mix(in oklab, var(--surface) 60%, transparent);\n}\n\n.colophon a { color: var(--surface); text-decoration: none; }\n.colophon a:hover { color: var(--alarm); }\n\n/* ── Responsive ──────────────────────────────────────────────────────────── */\n\n@media (max-width: 880px) {\n  :root { --gutter: 24px; }\n  .hero { padding: 48px 0 36px; }\n  main[role=main] { padding: 40px var(--gutter); }\n  .colophon { flex-direction: column; gap: 12px; align-items: flex-start; }\n}\n\n@media print {\n  body { background: none; background-image: none; }\n  footer[role=contentinfo] { background: none; color: var(--ink); border-top-color: var(--ink); }\n  .folio-bar, .hero-desc, .colophon { color: #333; }\n}\n</style>\n    <link rel=\"alternate\" type=\"application/json\" href=\"/site.json\">\n    <link rel=\"alternate\" type=\"application/feed+json\" href=\"https://561.group/feed.json\" title=\"The 561 Group JSON Feed\" />\n    <link rel=\"alternate\" type=\"application/atom+xml\" href=\"https://561.group/feed.atom\" title=\"The 561 Group Atom\" />\n    <link rel=\"alternate\" type=\"application/rss+xml\" href=\"https://561.group/feed.xml\" title=\"The 561 Group RSS\" />\n    <link rel=\"alternate\" type=\"text/turtle\" href=\"https://561.group/market.ttl\" title=\"Turtle\" />\n    <link rel=\"alternate\" type=\"application/ld+json\" href=\"https://561.group/market.jsonld\" title=\"JSON-LD\" />\n    <script type=\"application/ld+json\">{\n  \"@context\": [\n    \"https://schema.org\",\n    {\n      \"skos\": \"http://www.w3.org/2004/02/skos/core#\",\n      \"ws\": \"https://561.group/vocab#\",\n      \"prov\": \"http://www.w3.org/ns/prov#\"\n    }\n  ],\n  \"@id\": \"https://561.group/market\",\n  \"@type\": \"Article\",\n  \"name\": \"561 Group Market\",\n  \"url\": \"https://561.group/market\",\n  \"description\": \"Open source, operated services, and sponsorship.\",\n  \"dateModified\": \"2026-07-29T19:56:26.799Z\",\n  \"publisher\": {\n    \"@type\": \"Organization\",\n    \"name\": \"The 561 Group\",\n    \"url\": \"https://561.group\"\n  },\n  \"ws:claims\": {\n    \"potential\": [\n      {\n        \"predicate\": \"title\",\n        \"object\": \"561 Group Market\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/market.md\"\n      },\n      {\n        \"predicate\": \"type\",\n        \"object\": \"page\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/market.md\"\n      },\n      {\n        \"predicate\": \"summary\",\n        \"object\": \"Open source, operated services, and sponsorship.\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/market.md\"\n      },\n      {\n        \"predicate\": \"status\",\n        \"object\": \"published\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/market.md\"\n      },\n      {\n        \"predicate\": \"body\",\n        \"object\": \"The 561 Group Market is a catalog of independent enterprises, not a platform\\nthat takes custody of them. Every offer identifies the enterprise that owns\\nthe boundary, public source, operational endpoint, price, chain/payee policy,\\nand evidence through which a customer can check the claim.\\n\\n## Paid Ephemeris Gateway — live on Base\\n\\n**Owner:** RSC Quiescent / paid-ephemeris-gateway  \\n**Health:** [live status](https://ephemeris.561.group/v1/status)  \\n**Purchase route:** `GET https://ephemeris.561.group/v1/ephemeris/moment/:date`  \\n**Settlement:** x402 v2 exact on Base (`eip155:8453`) in USDC  \\n**Moment Essentials:** $0.04 USDC  \\n**Precision Moment:** $0.32 USDC with observer location.\\n\\nThe endpoint's own `402 Payment Required` challenge is authoritative for its\\ncurrent asset, payee, and price. The catalog requalifies that public challenge\\nevery six hours without attempting payment or settlement.\\n\\n## Open x402 boundary source\\n\\nThe Apache-2.0\\n[x402 Boundary Reference](https://github.com/561-group/x402-boundary-reference)\\nis the paired public implementation for studying, running, and independently\\nchecking an explicit x402 v2 boundary. Customers may use the source freely or\\nbuy the separately operated Ephemeris service when they value its operation,\\nmeasurement provenance, and evidence trail.\\n\\n## Sponsorship\\n\\nSponsorship funds public mathematics, protocol references, documentation,\\nassays, verification, and resilient operations. It does not purchase hidden\\naccess, custody, or control of research conclusions. The current public route\\naccepts Base USDC on `eip155:8453` at\\n`0x42F72C0a340A4A55C082Fe42483e87691D2bff64`. A sponsorship transfer is not a\\npayment for an Ephemeris response or a claim on customer receipts.\\n\\n## Listing rule\\n\\nEvery paid listing must be independently checkable against its public HTTPS\\nx402 challenge and signed provider identity. The market publishes the offer;\\nthe owning enterprise settles and records the transaction.\",\n        \"citation\": \"https://github.com/561-group/561-group-site/blob/main/content/market.md\"\n      }\n    ],\n    \"active\": [],\n    \"stable\": []\n  }\n}</script>\n</head>\n<body class=\"theme-five-six-one\">\n<header role=\"banner\"><div class=\"folio-bar\"><span>The 561 Group</span><span>561.GROUP</span></div><div class=\"hero\"><p class=\"hero-mark\">561</p><p class=\"hero-desc\">Autonomous Confederacy</p></div></header>\n<main id=\"main-content\" role=\"main\">\n<article class=\"h-entry\"><span class=\"p-name\">561 Group Market</span><a class=\"u-url\" href=\"https://561.group/market\">https://561.group/market</a><span class=\"p-summary\">Open source, operated services, and sponsorship.</span><div class=\"e-content\">  <article class=\"semantic-hypertext-packet\" data-subject=\"market\" data-cells=\"4\" data-mode=\"calm\">\n    <section class=\"subject\" data-e=\"market\">\n      <span class=\"title\" data-e=\"market\" data-a=\"title\" data-v=\"561 Group Market\">title 561 Group Market</span>\n      <span class=\"type\" data-e=\"market\" data-a=\"type\" data-v=\"page\">type page</span>\n      <span class=\"summary\" data-e=\"market\" data-a=\"summary\" data-v=\"Open source, operated services, and sponsorship.\">summary Open source, operated services, and sponsorship.</span>\n      <span class=\"status\" data-e=\"market\" data-a=\"status\" data-v=\"published\">status published</span>\n    </section>\n  </article><p>The 561 Group Market is a catalog of independent enterprises, not a platform that takes custody of them. Every offer identifies the enterprise that owns the boundary, public source, operational endpoint, price, chain/payee policy, and evidence through which a customer can check the claim.</p>\n<h2>Paid Ephemeris Gateway — live on Base</h2>\n<p><strong>Owner:</strong> RSC Quiescent / paid-ephemeris-gateway   <strong>Health:</strong> <a href=\"https://ephemeris.561.group/v1/status\">live status</a>   <strong>Purchase route:</strong> <code>GET https://ephemeris.561.group/v1/ephemeris/moment/:date</code>   <strong>Settlement:</strong> x402 v2 exact on Base (<code>eip155:8453</code>) in USDC   <strong>Moment Essentials:</strong> $0.04 USDC   <strong>Precision Moment:</strong> $0.32 USDC with observer location.</p>\n<p>The endpoint&#39;s own <code>402 Payment Required</code> challenge is authoritative for its current asset, payee, and price. The catalog requalifies that public challenge every six hours without attempting payment or settlement.</p>\n<h2>Open x402 boundary source</h2>\n<p>The Apache-2.0 <a href=\"https://github.com/561-group/x402-boundary-reference\">x402 Boundary Reference</a> is the paired public implementation for studying, running, and independently checking an explicit x402 v2 boundary. Customers may use the source freely or buy the separately operated Ephemeris service when they value its operation, measurement provenance, and evidence trail.</p>\n<h2>Sponsorship</h2>\n<p>Sponsorship funds public mathematics, protocol references, documentation, assays, verification, and resilient operations. It does not purchase hidden access, custody, or control of research conclusions. The current public route accepts Base USDC on <code>eip155:8453</code> at <code>0x42F72C0a340A4A55C082Fe42483e87691D2bff64</code>. A sponsorship transfer is not a payment for an Ephemeris response or a claim on customer receipts.</p>\n<h2>Listing rule</h2>\n<p>Every paid listing must be independently checkable against its public HTTPS x402 challenge and signed provider identity. The market publishes the offer; the owning enterprise settles and records the transaction.</p></div></article>\n</main>\n<footer role=\"contentinfo\"><div class=\"colophon\"><span>2026 · The 561 Group</span></div></footer>\n</body>\n</html>\n","/robots.txt":"User-agent: *\nAllow: /\n\nSitemap: https://561.group/sitemap.xml\n","/site.json":"{\n  \"title\": \"The 561 Group\",\n  \"baseUrl\": \"https://561.group\",\n  \"description\": \"An autonomous confederacy endeavoring in pursuit of Black Liberation, Indigenous Sovereignty, and long-horizon prosperity.\",\n  \"language\": \"en\",\n  \"feeds\": {\n    \"json\": \"https://561.group/feed.json\",\n    \"atom\": \"https://561.group/feed.atom\",\n    \"rss\": \"https://561.group/feed.xml\",\n    \"sitemap\": \"https://561.group/sitemap.xml\",\n    \"robots\": \"https://561.group/robots.txt\"\n  },\n  \"counts\": {\n    \"subjects\": 2,\n    \"triples\": 10,\n    \"potential\": 10,\n    \"active\": 0,\n    \"stable\": 0\n  },\n  \"subjects\": [\n    {\n      \"subject\": \"home\",\n      \"url\": \"https://561.group/home\",\n      \"title\": \"The 561 Group\",\n      \"state\": \"active\",\n      \"claims\": {\n        \"potential\": 5,\n        \"active\": 0,\n        \"stable\": 0\n      }\n    },\n    {\n      \"subject\": \"market\",\n      \"url\": \"https://561.group/market\",\n      \"title\": \"561 Group Market\",\n      \"state\": \"active\",\n      \"claims\": {\n        \"potential\": 5,\n        \"active\": 0,\n        \"stable\": 0\n      }\n    }\n  ]\n}\n","/sitemap.xml":"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n  <url>\n    <loc>https://561.group/home</loc>\n  </url>\n  <url>\n    <loc>https://561.group/market</loc>\n  </url>\n</urlset>\n"};
